function debounce(fn, delay) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}
const search = debounce(console.log, 200);
search('t'); search('te'); search('tea');
// Leading-only throttle:
function throttle(fn, ms) {
  let last = -Infinity;
  return (...a) => { if (performance.now()-last >= ms) {
    last = performance.now(); fn(...a);
  }};
}
